import { useEffect, useState } from "react";
import styles from "./IncidentsPage.module.css";
import { incidentsMock } from "../../shared/mocks/incidents";
import { fetchHotTickets } from "../../shared/api/alertsApi";

import { Header } from "../../widgets/Header";
import { InfoPanel } from "../../widgets/InfoPanel";
import { AlertsPanel } from "../../widgets/AlertsPanel";
import { IncidentsTable } from "../../widgets/IncidentsTable";

const ITEMS_PER_PAGE = 10;

export const IncidentsPage = () => {
  const [page, setPage] = useState(1);
  const [hotTickets, setHotTickets] = useState<number[]>([]);
  const [incidents, setIncidents] = useState<Incident[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadHotTickets();
  }, []);

  useEffect(() => {
  loadIncidents();
}, []);

  const loadHotTickets = async () => {
    const data = await fetchHotTickets();
    setHotTickets(data);
  };

  const loadIncidents = async () => {
  setLoading(true);
  const data = await incidentsApi.getIncidents();
  setIncidents(data);
  setLoading(false);
};

  const start = (page - 1) * ITEMS_PER_PAGE;
  const visible = incidentsMock.slice(start, start + ITEMS_PER_PAGE);

  return (
    <div className={styles.page}>

      {/* Header */}
      <Header />

      {/* Top section */}
      <section className={styles.top}>
        <InfoPanel />
        <AlertsPanel hotTickets={hotTickets} onRefresh={loadHotTickets} />
      </section>

      {/* Table */}
      <IncidentsTable
        visible={visible}
        start={start}
        total={incidentsMock.length}
        page={page}
        onPrev={() => setPage(page - 1)}
        onNext={() => setPage(page + 1)}
      />
    </div>
  );
};
